window.STORY_CHAPTERS["c77f040dd007893b2"]={"id":"c77f040dd007893b2","lines":[{"uid":"talk.ch15_4_0000#originalText","id":"talk.ch15_4_0000","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"第15章 开战 后篇","en":"Chapter 15: The Battle Begins (part 2)","ja":"第15章 開戦 後編"},"kind":"caption"},{"uid":"talk.ch15_4_1001#originalText","id":"talk.ch15_4_1001","speaker":{"cn":"侍卫","en":"Guard","ja":"衛士"},"text":{"cn":"报告！","en":"Reporting!","ja":"報告します!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1002#originalText","id":"talk.ch15_4_1002","speaker":{"cn":"侍卫","en":"Guard","ja":"衛士"},"text":{"cn":"法那提欧阁下打败了巨人族首领，迪索尔巴德阁下打败了哥布尔首领──","en":"Lady Fanatio faced the giant chief, and Sir Deusolbert faced the plains goblin chief...","ja":"ファナティオ殿がジャイアントの長をデュソルバート殿がゴブリンの長を――"},"kind":"dialogue"},{"uid":"talk.ch15_4_1003#originalText","id":"talk.ch15_4_1003","speaker":{"cn":"侍卫","en":"Guard","ja":"衛士"},"text":{"cn":"两人都拿下了战果！","en":"And they've defeated them both.","ja":"それぞれ討ち取りました!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1004#originalText","id":"talk.ch15_4_1004","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这样啊。","en":"I see.","ja":"そうか"},"kind":"dialogue"},{"uid":"talk.ch15_4_1005#originalText","id":"talk.ch15_4_1005","speaker":{"cn":"侍卫","en":"Guard","ja":"衛士"},"text":{"cn":"但敌军数量还是遥遥领先我军。","en":"That said, we are still overwhelmingly outnumbered by the enemy forces.","ja":"ですが、依然として敵軍の数は我が軍を大きく上回っています"},"kind":"dialogue"},{"uid":"talk.ch15_4_1006#originalText","id":"talk.ch15_4_1006","speaker":{"cn":"侍卫","en":"Guard","ja":"衛士"},"text":{"cn":"各部队随时都可能面临战线崩坏的危机。","en":"It's only a matter of time before the battle lines for each unit collapse.","ja":"各隊、戦線がいつ崩壊してもおかしくありません"},"kind":"dialogue"},{"uid":"talk.ch15_4_1007#originalText","id":"talk.ch15_4_1007","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"敌人的飞行战力有动静吗？","en":"What about the enemy's aerial forces?","ja":"敵の飛行戦力に動きは?"},"kind":"dialogue"},{"uid":"talk.ch15_4_1008#originalText","id":"talk.ch15_4_1008","speaker":{"cn":"侍卫","en":"Guard","ja":"衛士"},"text":{"cn":"目前并没有飞龙和米尼翁出动的迹象。","en":"So far, there's no sign of their flying wyrms or minions.","ja":"今のところ、飛竜やミニオンが出動した気配はありません"},"kind":"dialogue"},{"uid":"talk.ch15_4_1009#originalText","id":"talk.ch15_4_1009","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"唔……","en":"Hmm...","ja":"うむ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_1010#originalText","id":"talk.ch15_4_1010","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"眼下，人界军士兵与黑暗界军队正交战不止。","en":"Beneath me, the Human Empire's army and the forces of the Dark Realm are clashing.","ja":"眼下では、人界軍兵士と暗黒界の軍勢が刃を交えている"},"kind":"dialogue"},{"uid":"talk.ch15_4_1011#originalText","id":"talk.ch15_4_1011","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"每当武器挥下，士兵们便一个接一个丧失天命。","en":"With each swing of a sword, the life of another soldier is gone.","ja":"武器が振るわれるたびにひとつ、またひとつと兵士たちの天命が散っていく"},"kind":"dialogue"},{"uid":"talk.ch15_4_1012#originalText","id":"talk.ch15_4_1012","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"士兵们的性命化为神圣力，充满了整座狭长的峡谷。","en":"The lives of those soldiers turn into Sacred Power, filling the narrow ravine.","ja":"兵士たちの命は神聖力となり狭い峡谷に満ちあふれている"},"kind":"dialogue"},{"uid":"talk.ch15_4_1013#originalText","id":"talk.ch15_4_1013","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这片土地上的神圣力本应稀薄，却多得只要伸手就能感受到──","en":"Ordinarily, the Sacred Power in this ravine would be weak, yet I can feel the immense power in my hands...","ja":"本来、神聖力が薄いはずのこの地で手をかざせばそれとわかるほど多量の神聖力――"},"kind":"dialogue"},{"uid":"talk.ch15_4_1014#originalText","id":"talk.ch15_4_1014","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"代表现在有那么多的生命，正一个个回归天上……","en":"That shows just how many lives are ascending to the heavens right now.","ja":"それほど多くの命が、今まさに天へ還っている……"},"kind":"dialogue"},{"uid":"talk.ch15_4_1015#originalText","id":"talk.ch15_4_1015","speaker":{"cn":"雨缘","en":"Amayori","ja":"雨縁"},"text":{"cn":"啾？","en":"Krrr?","ja":"きゅる?"},"kind":"dialogue"},{"uid":"talk.ch15_4_1016#originalText","id":"talk.ch15_4_1016","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……没事的，雨缘。我会完成自己的使命──","en":"It's all right, Amayori. I shall fulfill my duty...","ja":"……大丈夫よ雨縁私は、自らの役目を――"},"kind":"dialogue"},{"uid":"talk.ch15_4_1017#originalText","id":"talk.ch15_4_1017","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"来了吗？可恶的哥布尔们……","en":"So. The goblins are here."},"kind":"dialogue"},{"uid":"talk.ch15_4_1018#originalText","id":"talk.ch15_4_1018","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"我等人界军有爱丽丝大人参战，就凭你们哥布尔是不可能攻破的。","en":"This Human Empire army, with Lady Alice at its core, will not be crushed by the likes of you."},"kind":"dialogue"},{"uid":"talk.ch15_4_1019#originalText","id":"talk.ch15_4_1019","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"多亏有你的支持，我才能在这条险峻的路上走到今天。","en":"Thanks to your support, I was able to walk this dangerous path until today."},"kind":"dialogue"},{"uid":"talk.ch15_4_1020#originalText","id":"talk.ch15_4_1020","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"谢谢你，艾尔多利耶。","en":"Thank you, Eldrie."},"kind":"dialogue"},{"uid":"talk.ch15_4_1021#originalText","id":"talk.ch15_4_1021","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"吾师爱丽丝啊，请妳原谅我日前在卢利特的无礼。","en":"Lady Alice, my mentor, please forgive me for how insensitive I was in Rulid one week ago."},"kind":"dialogue"},{"uid":"talk.ch15_4_1022#originalText","id":"talk.ch15_4_1022","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"而今日，我一定会用我的《霜鳞鞭》守护妳与人界。","en":"I promise you that I will atone for it today, by saving the Empire, and you, with my Frostscale Whip."},"kind":"dialogue"},{"uid":"talk.ch15_4_1023#originalText","id":"talk.ch15_4_1023","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"请吾师务必在空中见证妳传授予我的招式与术法！","en":"I will use all the skills and arts you so graciously taught me. Please, watch me from the sky!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1024#originalText","id":"talk.ch15_4_1024","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"尽管来吧！你们的对手是集成骑士艾尔多利耶‧辛赛西斯‧萨蒂汪！","en":"Come at me! I am your opponent! Integrity Knight, Eldrie Synthesis Thirty-One!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1025#originalText","id":"talk.ch15_4_1025","speaker":{"cn":"柯索吉","en":"Kosogi"},"text":{"cn":"……就是现在，丢啊！","en":"Now! Throw them!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1026#originalText","id":"talk.ch15_4_1026","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"那是……？","en":"What's that?"},"kind":"dialogue"},{"uid":"talk.ch15_4_1027#originalText","id":"talk.ch15_4_1027","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"这、这个是……","en":"This is...!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1028#originalText","id":"talk.ch15_4_1028","speaker":{"cn":"柯索吉","en":"Kosogi"},"text":{"cn":"小子们，快跑────！！","en":"Everyone, charrrge!!!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1029#originalText","id":"talk.ch15_4_1029","speaker":{"cn":"侍卫","en":"Guard"},"text":{"cn":"可恶……！休想通过这里……","en":"I won't let—"},"kind":"dialogue"},{"uid":"talk.ch15_4_1030#originalText","id":"talk.ch15_4_1030","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"等一下！现在挥剑会伤到自己人的！","en":"Stop! If we swing our swords now, we'll end up hitting each other!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1031#originalText","id":"talk.ch15_4_1031","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"得告诉后方的第二部队……得告诉连利阁下这件事才行！","en":"We have to let Sir Renly in the second unit behind us know what's happening!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1032#originalText","id":"talk.ch15_4_1032","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"可恶……我居然在爱丽丝大人的面前犯下这等失误……","en":"Ugh... I am ashamed... to fail so horribly in front of Lady Alice."},"kind":"dialogue"},{"uid":"talk.ch15_4_1033#originalText","id":"talk.ch15_4_1033","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"可恶的哥布尔们！居然使出卑劣的手段……","en":"Damn you, goblins! That was a dastardly trick..."},"kind":"dialogue"},{"uid":"talk.ch15_4_1101#originalText","id":"talk.ch15_4_1101","speaker":{"ja":"エルドリエ"},"text":{"ja":"来たか、ゴブリンども……"},"kind":"dialogue"},{"uid":"talk.ch15_4_1102#originalText","id":"talk.ch15_4_1102","speaker":{"ja":"エルドリエ"},"text":{"ja":"アリス様が参陣された我が人界軍は貴様ら如きに破れはせぬ"},"kind":"dialogue"},{"uid":"talk.ch15_4_1103#originalText","id":"talk.ch15_4_1103","speaker":{"ja":"アリス"},"text":{"ja":"そなたが支えてくれたから、私は険しい道を今日まで歩き続けることができました"},"kind":"dialogue"},{"uid":"talk.ch15_4_1104#originalText","id":"talk.ch15_4_1104","speaker":{"ja":"アリス"},"text":{"ja":"ありがとう、エルドリエ"},"kind":"dialogue"},{"uid":"talk.ch15_4_1105#originalText","id":"talk.ch15_4_1105","speaker":{"ja":"エルドリエ"},"text":{"ja":"我が師アリスよ、先日のルーリッドでのご無礼をお許しください"},"kind":"dialogue"},{"uid":"talk.ch15_4_1106#originalText","id":"talk.ch15_4_1106","speaker":{"ja":"エルドリエ"},"text":{"ja":"そして今日こそ、わが《霜鱗鞭》で御身と人界を守ってみせる"},"kind":"dialogue"},{"uid":"talk.ch15_4_1107#originalText","id":"talk.ch15_4_1107","speaker":{"ja":"エルドリエ"},"text":{"ja":"師からご教授頂いた技と術、上空から御照覧ください!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1108#originalText","id":"talk.ch15_4_1108","speaker":{"ja":"エルドリエ"},"text":{"ja":"さあ来い! お前らの相手は整合騎士エルドリエ・シンセシス・サーティワンだ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1109#originalText","id":"talk.ch15_4_1109","speaker":{"ja":"コソギ"},"text":{"ja":"……今だ、投げろ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1110#originalText","id":"talk.ch15_4_1110","speaker":{"ja":"エルドリエ"},"text":{"ja":"あれは……?"},"kind":"dialogue"},{"uid":"talk.ch15_4_1111#originalText","id":"talk.ch15_4_1111","speaker":{"ja":"エルドリエ"},"text":{"ja":"こ、これは……"},"kind":"dialogue"},{"uid":"talk.ch15_4_1112#originalText","id":"talk.ch15_4_1112","speaker":{"ja":"コソギ"},"text":{"ja":"てめぇらぁ、走れェェェェ!!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1113#originalText","id":"talk.ch15_4_1113","speaker":{"ja":"衛士"},"text":{"ja":"くっ、ここは通さない……"},"kind":"dialogue"},{"uid":"talk.ch15_4_1114#originalText","id":"talk.ch15_4_1114","speaker":{"ja":"エルドリエ"},"text":{"ja":"待て!今剣を振るえば、同士討ちになる!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1115#originalText","id":"talk.ch15_4_1115","speaker":{"ja":"エルドリエ"},"text":{"ja":"後ろの第2部隊に……レンリ殿に状況を伝えなければ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_1116#originalText","id":"talk.ch15_4_1116","speaker":{"ja":"エルドリエ"},"text":{"ja":"くっ……アリス様の目の前でこのような失態を……"},"kind":"dialogue"},{"uid":"talk.ch15_4_1117#originalText","id":"talk.ch15_4_1117","speaker":{"ja":"エルドリエ"},"text":{"ja":"ゴブリンどもめ!卑怯な策を……"},"kind":"dialogue"},{"uid":"talk.ch15_4_2001#originalText","id":"talk.ch15_4_2001","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"为什么哥布尔已经攻进这种地方来了？","en":"Why are the goblins this far back?","ja":"なんで、こんなところまでゴブリンが攻めてきてるのさ?"},"kind":"dialogue"},{"uid":"talk.ch15_4_2002#originalText","id":"talk.ch15_4_2002","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"赛尔，敌方数量比想像的多……只凭我们有可能挡不住！","en":"Zel, there are more than we thought. There might be too many for us to push back on our own!","ja":"ゼル、思ったより数が多いです……あたしたちだけでは食い止められないかも!"},"kind":"dialogue"},{"uid":"talk.ch15_4_2003#originalText","id":"talk.ch15_4_2003","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"真是的，不管怎么打都没完没了！","en":"Goodness, there's just no end to them!","ja":"まったく、倒しても倒してもキリがないよ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_2004#originalText","id":"talk.ch15_4_2004","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"负责守前面的连利仔在做什么！？","en":"Why isn't Renlicchi defending the area ahead like he's supposed to?!","ja":"この前を守ってるはずのレンリっちは何してるの!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_2005#originalText","id":"talk.ch15_4_2005","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch15_4_2006#originalText","id":"talk.ch15_4_2006","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"果然是个胆小鬼……","en":"I knew it... That coward.","ja":"やっぱり……腰抜け"},"kind":"dialogue"},{"uid":"talk.ch15_4_3001#originalText","id":"talk.ch15_4_3001","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……快站起来，该回到岗位上了。","en":"Get up. You have to go back to your position.","ja":"……立つんだ持ち場に戻らなきゃ"},"kind":"dialogue"},{"uid":"talk.ch15_4_3002#originalText","id":"talk.ch15_4_3002","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"可是……就算我在那里也只会碍事。无法使用武装完全支配术的集成骑士，根本……","en":"No. I'd only be in the way. With no Perfect Weapon Control, I'm no Integrity Knight.","ja":"いや……僕がいても、邪魔なだけだ武装完全支配術が使えない整合騎士なんて……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3003#originalText","id":"talk.ch15_4_3003","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"连利……连利……","en":"Renly... Renly...","ja":"レンリ……レンリ"},"kind":"dialogue"},{"uid":"talk.ch15_4_3004#originalText","id":"talk.ch15_4_3004","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch15_4_3005#originalText","id":"talk.ch15_4_3005","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你……坏掉了呢。","en":"You...seem to be broken.","ja":"あなた、壊れちゃってるわね"},"kind":"dialogue"},{"uid":"talk.ch15_4_3006#originalText","id":"talk.ch15_4_3006","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"坏……坏掉了……？","en":"B-Broken?","ja":"こ……壊れてる……?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3007#originalText","id":"talk.ch15_4_3007","speaker":{"cn":"裘迪鲁金","en":"Chudelkin","ja":"チュデルキン"},"text":{"cn":"失败品！呵呵、呵呵呵呵！","en":"You're a failure! Hee-hee-ho-ho!","ja":"失敗作ゥ!ホホ、ホホホオゥ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3008#originalText","id":"talk.ch15_4_3008","speaker":{"cn":"裘迪鲁金","en":"Chudelkin","ja":"チュデルキン"},"text":{"cn":"没用的骑士！","en":"A defective knight!","ja":"出来損ないの、騎士!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3009#originalText","id":"talk.ch15_4_3009","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"连利，看来我只能将你冻结了。","en":"Renly, it seems I have no choice but to punish you to cryostasis.","ja":"レンリ、あなたは凍結処分にするしかないみたいね"},"kind":"dialogue"},{"uid":"talk.ch15_4_3010#originalText","id":"talk.ch15_4_3010","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"《双翼刃》明明选你当主人了，你却完全无法使用武装完全支配术。","en":"Those Double-Winged Blades chose you, but you've never achieved Perfect Weapon Control with them.","ja":"その《雙翼刃》が主に選んだというのにただの一度も武装完全支配術を使えないんだもの"},"kind":"dialogue"},{"uid":"talk.ch15_4_3011#originalText","id":"talk.ch15_4_3011","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"身为骑士，你缺乏了某种重要的东西。","en":"As a knight, you're lacking something crucial.","ja":"あなたには、騎士として大切なものが欠けている"},"kind":"dialogue"},{"uid":"talk.ch15_4_3012#originalText","id":"talk.ch15_4_3012","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"──晚安，连利。","en":"Goodnight, Renly.","ja":"――おやすみなさい、レンリ"},"kind":"dialogue"},{"uid":"talk.ch15_4_3013#originalText","id":"talk.ch15_4_3013","speaker":{"cn":"裘迪鲁金","en":"Chudelkin","ja":"チュデルキン"},"text":{"cn":"喔喔！","en":"Whoa!","ja":"おおゥ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3014#originalText","id":"talk.ch15_4_3014","speaker":{"cn":"裘迪鲁金","en":"Chudelkin","ja":"チュデルキン"},"text":{"cn":"居然能让司祭大人亲自对你道晚安，真是个幸福的骑士！","en":"For Her Eminence to say goodnight to you... What a lucky knight you are!","ja":"猊下におやすみを言ってもらえるとはなんて幸せな騎士なんでしょゥ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3015#originalText","id":"talk.ch15_4_3015","speaker":{"cn":"裘迪鲁金","en":"Chudelkin","ja":"チュデルキン"},"text":{"cn":"真令人羡慕！","en":"I'm so jealous!","ja":"うらやましィ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3016#originalText","id":"talk.ch15_4_3016","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"像我这种人，不管在不在场都一样……","en":"It doesn't matter whether I exist or not.","ja":"僕なんか、いてもいなくても同じなんだ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3017#originalText","id":"talk.ch15_4_3017","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"缇洁，这里怎么样？","en":"Tiese, what about here?","ja":"ティーゼ、ここはどう?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3018#originalText","id":"talk.ch15_4_3018","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"嗯，这个帐篷应该没问题，罗妮耶。","en":"Yes, this tent looks safe, Ronie.","ja":"うん、この天幕なら大丈夫そうだね、ロニエ"},"kind":"dialogue"},{"uid":"talk.ch15_4_3019#originalText","id":"talk.ch15_4_3019","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"啊！？","en":"Huh?!","ja":"はっ!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3020#originalText","id":"talk.ch15_4_3020","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"将学长藏进里面，我们在外面守着入口吧。","en":"Let's hide him in the back and guard the entrance.","ja":"先輩を奥に隠して、あたしたちは入り口を守りましょう"},"kind":"dialogue"},{"uid":"talk.ch15_4_3021#originalText","id":"talk.ch15_4_3021","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"里面很暗，小心一点……咦！？","en":"It's dark, so be careful... Huh?!","ja":"暗いから気をつけて……っ!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3022#originalText","id":"talk.ch15_4_3022","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"有人在吗！？","en":"Is someone there?","ja":"誰かいるの!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3023#originalText","id":"talk.ch15_4_3023","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……我不是敌人。抱歉吓到妳们了。","en":"I'm not the enemy. I apologize for startling you.","ja":"……敵じゃないよ驚かせてすまない"},"kind":"dialogue"},{"uid":"talk.ch15_4_3024#originalText","id":"talk.ch15_4_3024","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"骑……骑士大人！抱歉失礼了！","en":"S-Sir Knight! Forgive our rudeness!","ja":"き……騎士様!失礼いたしました!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3025#originalText","id":"talk.ch15_4_3025","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"哪里……是我不该吓到妳们。而且……我已经不是集成骑士了。","en":"No, it's my fault for scaring you. And besides, I'm not... an Integrity Knight anymore.","ja":"いや……脅かした僕が悪いそれに、僕はもう……整合騎士じゃない"},"kind":"dialogue"},{"uid":"talk.ch15_4_3026#originalText","id":"talk.ch15_4_3026","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"咦……？","en":"Huh?!","ja":"えっ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3027#originalText","id":"talk.ch15_4_3027","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我刚才丢下自己担纲的区域逃到这里来了，最前线已经开始战斗。","en":"I abandoned my post, just now. And the fighting has already begun on the front lines.","ja":"さっき、持ち場を放り出して、逃げてきたんだよもう最前線では戦闘が開始されている"},"kind":"dialogue"},{"uid":"talk.ch15_4_3028#originalText","id":"talk.ch15_4_3028","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"本该由我指挥的前线部队，现在应该一片骚动吧。甚至有可能有人死了。","en":"The unit I was supposed to command must be in a panic now. I'm sure there have been some deaths, too.","ja":"今頃、僕が指揮するはずの部隊は大騒ぎだろう死者だって出ているはずだ"},"kind":"dialogue"},{"uid":"talk.ch15_4_3029#originalText","id":"talk.ch15_4_3029","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"结果我却躲着无法动弹，我这样哪有资格当骑士？","en":"And yet, I can't bring myself to leave this place, so how can I call myself a knight?","ja":"なのに、ここから動けない僕が騎士なんかであるものか"},"kind":"dialogue"},{"uid":"talk.ch15_4_3030#originalText","id":"talk.ch15_4_3030","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch15_4_3031#originalText","id":"talk.ch15_4_3031","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"抱歉我们没先报上名。我们是隶属补给部队的罗妮耶‧阿拉贝鲁初等练士──","en":"We haven't introduced ourselves yet. I'm Primary Trainee Ronie Arabel with the Supply Corps.","ja":"申し遅れました。私たちは、補給部隊所属のロニエ・アラベル初等練士と――"},"kind":"dialogue"},{"uid":"talk.ch15_4_3032#originalText","id":"talk.ch15_4_3032","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"和缇洁‧休特里涅初等练士。然后这位是……","en":"And this is Primary Trainee Tiese Schtrinen. And this is...","ja":"ティーゼ・シュトリーネン初等練士そしてこちらが……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3033#originalText","id":"talk.ch15_4_3033","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"桐人上级修剑士。","en":"Elite Disciple Kirito.","ja":"キリト上級修剣士どのです"},"kind":"dialogue"},{"uid":"talk.ch15_4_3034#originalText","id":"talk.ch15_4_3034","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"桐人……？就是打倒最高司祭大人的……","en":"Kirito? The one who defeated the Pontifex?","ja":"キリト……?あの、最高司祭様を倒した……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3035#originalText","id":"talk.ch15_4_3035","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"那个……我无法对骑士大人您的状况有任何的评论。","en":"Please, Sir Knight...we have no right to comment on your circumstances.","ja":"あの……私は、騎士様のご事情については何を申し上げることもできません"},"kind":"dialogue"},{"uid":"talk.ch15_4_3036#originalText","id":"talk.ch15_4_3036","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"因为我们虽然是守备军的一员，但是也没有到前线作战，而是像现在这样退到了后方。","en":"We are members of the guardian army, too, but hang in the rear, rather than fighting at the line of battle.","ja":"私たちだって、守備軍の一員でありながら前線で戦うことなく後方に下がっているのですから"},"kind":"dialogue"},{"uid":"talk.ch15_4_3037#originalText","id":"talk.ch15_4_3037","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……可是这就是我们现在的任务。","en":"But...that is our duty for now.","ja":"……でも、いまは、それが私たちの任務なのです"},"kind":"dialogue"},{"uid":"talk.ch15_4_3038#originalText","id":"talk.ch15_4_3038","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我们必须守护，骑士爱丽丝大人托付给我们的这个人……","en":"Lady Alice instructed us to dedicate ourselves to his protection.","ja":"騎士アリス様から託された、この方を絶対に守り抜くことが……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3039#originalText","id":"talk.ch15_4_3039","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"爱丽丝……爱丽丝‧辛赛西斯‧萨蒂……","en":"Alice... Alice Synthesis Thirty...","ja":"アリス……アリス・シンセシス・サーティ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3040#originalText","id":"talk.ch15_4_3040","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"骑士大人，我知道这是任性的请求，可以请您帮帮我们吗？","en":"Sir Knight, forgive me if I'm being forward, but would you be so kind as to help us out?","ja":"騎士さま、勝手なことを申すようですがどうか、私たちに手を貸してくださいませんか?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3041#originalText","id":"talk.ch15_4_3041","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"老实说，光靠我们两个，连对付一只哥布尔都有困难。","en":"To be honest, defeating even a single goblin is beyond our abilities.","ja":"正直、私たちふたりでは、たった1匹のゴブリンの相手すらも覚束ないのです"},"kind":"dialogue"},{"uid":"talk.ch15_4_3042#originalText","id":"talk.ch15_4_3042","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我们无论如何……无论如何都必须保护桐人学长才行！","en":"No matter what... No matter what, we must keep Kirito safe.","ja":"なんとしても……なんとしても、私たちはキリト先輩をお守りしなくてはならないのです!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3043#originalText","id":"talk.ch15_4_3043","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"嘎啊啊！","en":"Graaa!","ja":"ガアアッ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_3044#originalText","id":"talk.ch15_4_3044","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不会吧！？已经攻到这里来了吗……？","en":"No way! They're here already?","ja":"うそ!?もうこんな後方まで……?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3045#originalText","id":"talk.ch15_4_3045","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"有烟……有奇怪颜色的烟飘过来，从烟里面跑出好多人……","en":"Smoke... There's some kind of weird smoke wafting in. And there's lots of people coming out of it!","ja":"煙が……変な色の煙が流れてきている煙の中から、たくさんの人が……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3046#originalText","id":"talk.ch15_4_3046","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"啊！？","en":"Huh?!","ja":"はっ!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3047#originalText","id":"talk.ch15_4_3047","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"──哥布尔！？","en":"A goblin?!","ja":"――ゴブリン!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_3048#originalText","id":"talk.ch15_4_3048","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"喔喔……是白伊武姆的小女孩……妳们是我的猎物……","en":"Ooh! I found some white Ium girls. What a haul for me.","ja":"おほう……白イウムの、娘っこだぁ……おれの獲物だぁ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3049#originalText","id":"talk.ch15_4_3049","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"缇……缇洁……","en":"Tie...Tiese...","ja":"ティ……ティーゼ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_3050#originalText","id":"talk.ch15_4_3050","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"唔……呼、呼、呼…………","en":"Oof! Huff... Huff...","ja":"くっ……はあ、はあ、はあ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4001#originalText","id":"talk.ch15_4_4001","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"跟其他的骑士们……和书中读过的哥布尔完全不一样……","en":"He's...completely different. Completely unlike the goblins I read about in books...","ja":"ぜんぜん……違う他の騎士たちや、本で読んだゴブリンとは……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4002#originalText","id":"talk.ch15_4_4002","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"原来牠们是如此丑恶的存在吗……？","en":"Are all goblins really this hideous?","ja":"あんなに、醜悪なものなのか……?"},"kind":"dialogue"},{"uid":"talk.ch15_4_4003#originalText","id":"talk.ch15_4_4003","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"缇……缇洁……","en":"Tie...Tiese...","ja":"ティ……ティーゼ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4004#originalText","id":"talk.ch15_4_4004","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我、我得站起来……必须打倒那些哥布尔们，救出她们……","en":"I...I have to stand up... I have to defeat that goblin and save those girls.","ja":"た、立たなきゃ……あのゴブリンたちを倒して、彼女たちを……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4005#originalText","id":"talk.ch15_4_4005","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……身、身体动不了。我的身体为什么……","en":"I...I can't move. Why can't I...?","ja":"……う、動かないどうして、この体は……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4006#originalText","id":"talk.ch15_4_4006","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"既然是集成骑士的话，那种哥布尔就算有一千只都能打倒才对的啊……！","en":"He's just one goblin. An Integrity Knight should be able to defeat 1000 of his kind at once.","ja":"あんなゴブリンなんて、整合騎士であれば1000体だって倒せるはずなのに……!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4007#originalText","id":"talk.ch15_4_4007","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"咕呼……看起来好好吃……","en":"Mmm. You look tasty.","ja":"ぐふぅ……うんまそうだぁ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4008#originalText","id":"talk.ch15_4_4008","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我、我必须站起来……","en":"I...I must stand up...","ja":"た、立たなければ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4009#originalText","id":"talk.ch15_4_4009","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"快……快点退下！不然……！","en":"S-Stay back! Or else I'll...","ja":"さ……下がりなさい!さもなくば……!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4010#originalText","id":"talk.ch15_4_4010","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"咕呵呵呵……","en":"Hehehe...","ja":"ぐふふふ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4011#originalText","id":"talk.ch15_4_4011","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"……！？","en":"Hm?!","ja":"……っ!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_4012#originalText","id":"talk.ch15_4_4012","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"……怎么回事……？","en":"...What...is this...?","ja":"……なんだぁ、こりゃあ?"},"kind":"dialogue"},{"uid":"talk.ch15_4_4013#originalText","id":"talk.ch15_4_4013","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"涅尔，这附近的哥布尔全部都被我收拾掉了，不过还会再来。","en":"Nel, I cleaned up all the goblins around here, but more will come.","ja":"ネル、この近くのゴブリンは全部片付けたけどまだ来るよ"},"kind":"dialogue"},{"uid":"talk.ch15_4_4014#originalText","id":"talk.ch15_4_4014","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"我看还是移动比较好。","en":"Maybe we should move.","ja":"移動した方がいいかも"},"kind":"dialogue"},{"uid":"talk.ch15_4_4015#originalText","id":"talk.ch15_4_4015","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"嗯，我知道了，赛尔。","en":"Mm. Got it, Zel.","ja":"ん、わかりました、ゼル"},"kind":"dialogue"},{"uid":"talk.ch15_4_4016#originalText","id":"talk.ch15_4_4016","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"啊……","en":"Oh...","ja":"あ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4017#originalText","id":"talk.ch15_4_4017","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"请问……","en":"Excuse me...","ja":"あの……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4018#originalText","id":"talk.ch15_4_4018","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我是里涅尔，她是费赛尔，两个都是骑士见习生。","en":"I am Linel, and this is Fizel. We're Knights-in-training.","ja":"あたしはリネル、こっちはフィゼルふたりとも見習い騎士です"},"kind":"dialogue"},{"uid":"talk.ch15_4_4019#originalText","id":"talk.ch15_4_4019","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是……是的，曾经在训练中见过两位。","en":"Y-Yes, I know. We saw you during exercises.","ja":"は、はい、訓練中にお見かけしました"},"kind":"dialogue"},{"uid":"talk.ch15_4_4020#originalText","id":"talk.ch15_4_4020","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我们是缇洁‧休特里涅练士与罗妮耶‧阿拉贝鲁练士。","en":"We are Tiese Schtrinen and Ronie Arabel, Primary Trainees.","ja":"ティーゼ・シュトリーネン練士とロニエ・アラベル練士です"},"kind":"dialogue"},{"uid":"talk.ch15_4_4021#originalText","id":"talk.ch15_4_4021","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"谢……谢谢您救了我们。","en":"Th-Thank you for saving us.","ja":"た……助けて頂いて、ありがとうございます"},"kind":"dialogue"},{"uid":"talk.ch15_4_4022#originalText","id":"talk.ch15_4_4022","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"非常感谢两位……！","en":"Thank you!","ja":"ありがとうございます……!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4023#originalText","id":"talk.ch15_4_4023","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"能不能得救还不知道呢。","en":"You might be getting ahead of yourselves.","ja":"まだ助かったかはわからないです"},"kind":"dialogue"},{"uid":"talk.ch15_4_4024#originalText","id":"talk.ch15_4_4024","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"因为第一部队与第二部队的左翼被烟幕笼罩的期间，好像有超过一百只以上的哥布尔穿越防卫线了。","en":"Over a hundred goblins broke through the left flanks of the First and Second units under the cover of a smoke screen.","ja":"第一部隊と第二部隊の左翼が煙幕に巻かれている間にゴブリンが100匹以上も来たみたいですから"},"kind":"dialogue"},{"uid":"talk.ch15_4_4025#originalText","id":"talk.ch15_4_4025","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"应该指挥第二部队左翼的高等骑士大人，在这种地方做什么呢？","en":"And what is the elite knight who is supposed to be commanding the left flank of the Second Unit doing here?","ja":"その第二部隊で指揮を執ってるはずの上位騎士様がこんなところで何をしてるんですか?"},"kind":"dialogue"},{"uid":"talk.ch15_4_4026#originalText","id":"talk.ch15_4_4026","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"你的部下正在烟幕当中不知所措哟？","en":"Your subordinates are running around in a panic within the smoke, you know?","ja":"あなたの部下たち、煙幕の中で右往左往してますよ?"},"kind":"dialogue"},{"uid":"talk.ch15_4_4027#originalText","id":"talk.ch15_4_4027","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……和妳们无关。把那两个人和病人带到安全的地方去吧。","en":"It has nothing to do with you. Take these two and their sick patient to a safe place.","ja":"……君たちには関係ない。そのふたりと病人を安全なところまで連れて行ってくれ"},"kind":"dialogue"},{"uid":"talk.ch15_4_4028#originalText","id":"talk.ch15_4_4028","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch15_4_4029#originalText","id":"talk.ch15_4_4029","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……！","en":"...!","ja":"……っ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4030#originalText","id":"talk.ch15_4_4030","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"……真是个没用的家伙，既然身为高等骑士，总该有些实力吧。","en":"You might be a terrible coward... but you are an elite knight, so you possess some kind of strength.","ja":"……とんだ腰抜けですが、上位騎士であるからには何らかの強さを持っているんでしょう"},"kind":"dialogue"},{"uid":"talk.ch15_4_4031#originalText","id":"talk.ch15_4_4031","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"你要感谢那位被你称为病人的剑士哟。","en":"You ought to be grateful to the swordsman you called \"a sick patient.\"","ja":"あなたが病人と呼んだそこの剣士に感謝するんですね"},"kind":"dialogue"},{"uid":"talk.ch15_4_4032#originalText","id":"talk.ch15_4_4032","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"──这是什么意思……？","en":"What...do you mean?","ja":"――それは、どういう……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4033#originalText","id":"talk.ch15_4_4033","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"两名练士，和桐人一起跟过来吧。","en":"Trainees!Bring Kirito and follow me.","ja":"練士たち、キリトと一緒に着いてきなさい"},"kind":"dialogue"},{"uid":"talk.ch15_4_4034#originalText","id":"talk.ch15_4_4034","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"涅尔，来了哟！有八……不对，是十只！","en":"Nel, they're here! Eight...no, ten of them!","ja":"ネル、来たよ!8……じゃなくて、10匹はいる!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4035#originalText","id":"talk.ch15_4_4035","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"居……居然有十只之多……","en":"T-Ten of them?","ja":"じゅ……10匹も……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4036#originalText","id":"talk.ch15_4_4036","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"收回命令，暂时在这里待机。我先去把那些哥布尔收拾掉。","en":"Ignore that command. Stay here for a while. We will go clean up the goblins.","ja":"命令撤回です、しばらくここで待機ゴブリンたちを片付けてきます"},"kind":"dialogue"},{"uid":"talk.ch15_4_4037#originalText","id":"talk.ch15_4_4037","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好……好的，骑士大人。","en":"Y-Yes, Lady Knight.","ja":"は……はい、騎士様"},"kind":"dialogue"},{"uid":"talk.ch15_4_4038#originalText","id":"talk.ch15_4_4038","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch15_4_4039#originalText","id":"talk.ch15_4_4039","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"啊！？","en":"Huh?!","ja":"はっ!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_4040#originalText","id":"talk.ch15_4_4040","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"……哦？","en":"Well, well...","ja":"……ほう"},"kind":"dialogue"},{"uid":"talk.ch15_4_4041#originalText","id":"talk.ch15_4_4041","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"站……站住！要是你再靠近，我就要攻击了！","en":"S-Stop right there! If you come any closer... I'll slash you!","ja":"と……止まりなさい!それ以上近づけば、斬ります!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4042#originalText","id":"talk.ch15_4_4042","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch15_4_4043#originalText","id":"talk.ch15_4_4043","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"我们终于来到这里了，连利。","en":"We made it to the end, Renly!","ja":"とうとうここまで来たな、レンリ"},"kind":"dialogue"},{"uid":"talk.ch15_4_4044#originalText","id":"talk.ch15_4_4044","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"是啊，终于来到这了。","en":"Yeah, we did it.","ja":"ああ、ついに来た"},"kind":"dialogue"},{"uid":"talk.ch15_4_4045#originalText","id":"talk.ch15_4_4045","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"今天我一定会赢，连利！","en":"This one's mine!","ja":"今日は俺が勝たせてもらうぜ、レンリ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4046#originalText","id":"talk.ch15_4_4046","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我也不会输的！","en":"Hey, don't count me out yet!","ja":"僕だって!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4047#originalText","id":"talk.ch15_4_4047","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"来吧，我要上了！","en":"Let's goo!","ja":"さあ、行くぞ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4101#originalText","id":"talk.ch15_4_4101","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"喝啊！","en":"Yaah!","ja":"やあっ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4102#originalText","id":"talk.ch15_4_4102","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"嘿嘿，你就这点程度？","en":"Heh, is that all you've got?","ja":"へへ、その程度か!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4103#originalText","id":"talk.ch15_4_4103","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"看招！","en":"You're mine!","ja":"もらった!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4104#originalText","id":"talk.ch15_4_4104","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"小意思！","en":"Oh, no you don't!","ja":"なんのっ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_4105#originalText","id":"talk.ch15_4_4105","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"咦……？","en":"Huh?!","ja":"えっ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_4106#originalText","id":"talk.ch15_4_4106","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"连……利……","en":"Ren...ly...","ja":"レ……ンリ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5001#originalText","id":"talk.ch15_4_5001","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"呼……呼……","en":"Huff... Huff...","ja":"はあ、はあ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5002#originalText","id":"talk.ch15_4_5002","speaker":{"cn":"缇洁","en":"Tiese"},"text":{"cn":"快、快点退下！不然……","en":"S-Stay back! Or else!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5003#originalText","id":"talk.ch15_4_5003","speaker":{"cn":"哥布尔","en":"Goblin"},"text":{"cn":"咕呼……看起来好好吃……","en":"Mmm. You look tasty."},"kind":"dialogue"},{"uid":"talk.ch15_4_5004#originalText","id":"talk.ch15_4_5004","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我、我必须站起来……","en":"I...I must stand up...","ja":"た、立たなければ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5005#originalText","id":"talk.ch15_4_5005","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"这、这个声音是……？","en":"Wh-What's this sound?","ja":"こ、この音は……?"},"kind":"dialogue"},{"uid":"talk.ch15_4_5006#originalText","id":"talk.ch15_4_5006","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"你……你想要救她们吗？","en":"Are you... Are you trying to save them?","ja":"き、君は……君は、あの子たちを助けようというのか"},"kind":"dialogue"},{"uid":"talk.ch15_4_5007#originalText","id":"talk.ch15_4_5007","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"你明明无法拔剑也无法站起来，不只这样，甚至连开口说话都不行……","en":"Even though you can't stand or draw your sword, not to mention you can't even speak!","ja":"立つことも、抜剣することもそれどころか喋ることすらできないのに……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5008#originalText","id":"talk.ch15_4_5008","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"结果你却……我……","en":"And yet...I'm...","ja":"それなのに、僕は……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5009#originalText","id":"talk.ch15_4_5009","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"连利……你要成为一位……杰出的骑士……连我的份一起……","en":"Renly... I want you... to become a great knight... Do it for me...","ja":"レンリ……お前は……立派な騎士に、なれ……俺の、分まで……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5010#originalText","id":"talk.ch15_4_5010","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"──！","en":"...Ugh!!!","ja":"――っ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5011#originalText","id":"talk.ch15_4_5011","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"嘎嘿嘿嘿！","en":"Ohh-hehe!","ja":"グヘヘェッ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5012#originalText","id":"talk.ch15_4_5012","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"呜……！","en":"Gugh!","ja":"くぅ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5013#originalText","id":"talk.ch15_4_5013","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"喝啊啊啊啊！","en":"Yahhh!","ja":"うぉりゃああっ"},"kind":"dialogue"},{"uid":"talk.ch15_4_5013_2#originalText","id":"talk.ch15_4_5013_2","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"……咦？","en":"...Huh?","ja":"……あれ?"},"kind":"dialogue"},{"uid":"talk.ch15_4_5014#originalText","id":"talk.ch15_4_5014","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"呼、呼、呼……","en":"Huff... Huff...","ja":"はあ、はあ、はあ……"},"kind":"dialogue"},{"uid":"talk.ch15_4_5015#originalText","id":"talk.ch15_4_5015","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"骑士大人，真的很感谢您！","en":"Sir Knight, thank you...very much!","ja":"騎士さま、ありがとうございます!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5016#originalText","id":"talk.ch15_4_5016","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"您救了我们对吧！","en":"You saved us!","ja":"助けてくださったんですね!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5017#originalText","id":"talk.ch15_4_5017","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"妳们留在这里保护桐人先生！","en":"I want you two to stay here and protect Kirito.","ja":"君たちは、ここでキリトさんを守っていて!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5018#originalText","id":"talk.ch15_4_5018","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是、是的！","en":"R-Right!","ja":"は、はい!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5019#originalText","id":"talk.ch15_4_5019","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我的名字叫连利！集成骑士连利‧辛赛西斯‧推尼赛门！","en":"My name is Renly! Integrity Knight, Renly Synthesis Twenty-Seven!","ja":"僕の名はレンリ!整合騎士レンリ・シンセシス・トゥエニセブン!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5020#originalText","id":"talk.ch15_4_5020","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"若是想要我的首级，就抱着丧命的觉悟放马过来！","en":"If it's my head you want, be ready to lay down your lives for it!","ja":"この首が欲しければ、命を投げ出す覚悟でかかってこい!"},"kind":"dialogue"},{"uid":"talk.ch15_4_5021#originalText","id":"talk.ch15_4_5021","speaker":{"cn":"哥布尔","en":"Goblin","ja":"ゴブリン"},"text":{"cn":"是大将的首级！！！","en":"It's the captain's head!","ja":"大将首だぁ!!!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6001#originalText","id":"talk.ch15_4_6001","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……没问题！只要再撑一下子──","en":"I can do this. If I hold out just a little longer,","ja":"……いける!もう少しだけ持ちこたえれば――"},"kind":"dialogue"},{"uid":"talk.ch15_4_6002#originalText","id":"talk.ch15_4_6002","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"烟幕散去的前线应该就会有援军来了。","en":"reinforcements should arrive from the front lines, where the smoke- screen's thinned out.","ja":"煙幕が薄れた前線から援軍が来てくれるはずだ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6003#originalText","id":"talk.ch15_4_6003","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"……嘿嘿嘿。","en":"Heh! Heh! Heh!","ja":"……へっへっへ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6004#originalText","id":"talk.ch15_4_6004","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"你就是大将吗？","en":"Are you the captain?","ja":"お前が大将か"},"kind":"dialogue"},{"uid":"talk.ch15_4_6005#originalText","id":"talk.ch15_4_6005","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"没错，我是山地哥布尔族的首领柯索吉。哎呀，你居然杀了一堆我的部下。","en":"Yeah. I'm the Chief of the Mountain Goblins, Kosogi. You've killed quite a number of them, haven't you.","ja":"おう、山ゴブリンの族長コソギだあーあ、派手に殺してくれたよなあ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6006#originalText","id":"talk.ch15_4_6006","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"没想到有集成骑士留在这么后面的战区，真是太令我意外了。","en":"Who would've thought there'd be an Integrity Knight this far back? Really, my guess was wrong!","ja":"まさかこんな後ろに整合騎士が居残ってるとはねえまったくアテがはずれちまったよ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6007#originalText","id":"talk.ch15_4_6007","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"你们的战争将会在此终结！","en":"This is where your war ends!","ja":"ここでお前たちの戦争は終わりだ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6008#originalText","id":"talk.ch15_4_6008","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"《双翼刃》！！","en":"Double-Winged Blades!!!","ja":"《雙翼刃》!!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6009#originalText","id":"talk.ch15_4_6009","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"……哼！","en":"Humph!","ja":"……フン!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6010#originalText","id":"talk.ch15_4_6010","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"什么……！？","en":"What?!","ja":"なっ……!?"},"kind":"dialogue"},{"uid":"talk.ch15_4_6011#originalText","id":"talk.ch15_4_6011","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"看到哥布尔这么能打你很惊讶吧，小子。但我才想这么对你说呢。","en":"The look on your face says, “But you're just a goblin!\" boy. But this is what I have to say about it.","ja":"ゴブリンのくせに……ってツラだな、坊やだが俺としちゃこう言わせてもらいたいね"},"kind":"dialogue"},{"uid":"talk.ch15_4_6012#originalText","id":"talk.ch15_4_6012","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"亏你是个伟大的骑士居然这么没用。","en":"\"You call yourself an esteemed knight?\"","ja":"お偉い騎士さまのくせに、ってな"},"kind":"dialogue"},{"uid":"talk.ch15_4_6013#originalText","id":"talk.ch15_4_6013","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"我听说集成骑士都拥有一骑当千的实力……看来你并不是这样呢。","en":"A single Integrity Knight is a match for a thousand. That's what I was told. But that's not the case for you, huh?","ja":"整合騎士は一騎当千……そう聞いていたんだがどうやらお前さんはそうでもないようだな?"},"kind":"dialogue"},{"uid":"talk.ch15_4_6014#originalText","id":"talk.ch15_4_6014","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"所以你才躲在这么后面，我没说错吧？","en":"That's why you've been hiding all the way back here. Am I right?","ja":"だからこんな後ろに隠れてたそうなんだろう?"},"kind":"dialogue"},{"uid":"talk.ch15_4_6015#originalText","id":"talk.ch15_4_6015","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我果然是个失败品吗……","en":"Am I a failure after all?","ja":"僕はやっぱり失敗作だったのか"},"kind":"dialogue"},{"uid":"talk.ch15_4_6015_2#originalText","id":"talk.ch15_4_6015_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"即使如此──","en":"Even if I am...","ja":"――だとしても"},"kind":"dialogue"},{"uid":"talk.ch15_4_6016#originalText","id":"talk.ch15_4_6016","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"对，没错，我是个失败品骑士……可是，你可别搞错了。","en":"Yeah, that's right. As a knight, I am a failure. Even so, don't get the wrong idea.","ja":"ああ、そうさ。僕は失敗作の騎士だだけどね……勘違いするなよ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6017#originalText","id":"talk.ch15_4_6017","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"没用的是我，不是这家伙。","en":"I'm the one who's defective, not these. ","ja":"出来損ないなのは僕であってこいつじゃない"},"kind":"dialogue"},{"uid":"talk.ch15_4_6018#originalText","id":"talk.ch15_4_6018","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"──飞舞吧，双翼！","en":"Take flight... Double Wings! ","ja":"――飛べ、雙翼!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6019#originalText","id":"talk.ch15_4_6019","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"那个人手中的两把剑产生了共鸣，宛如彼此互相吸引。","en":"The dual swords he held were resonating with each other... Calling out to each other.","ja":"あの人の持つ2本の剣は、共鳴していたお互いに惹かれ合うように"},"kind":"dialogue"},{"uid":"talk.ch15_4_6020#originalText","id":"talk.ch15_4_6020","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"在我的体内，一定也残留着像这把《双翼刃》一样会产生共鸣的灵魂！","en":"So I'm certain that a soul that can resonate like these Double-Winged blades still resides inside of me!","ja":"僕の中にも、きっとこの《雙翼刃》のように共鳴する魂が残っているはずだ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6021#originalText","id":"talk.ch15_4_6021","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"对，我是个属于失败品的集成骑士。连站上战场都有问题。","en":"Yes. I am a failure as a knight. I can't even stand on the field of battle like I'm supposed to.","ja":"そう、僕は失敗作の整合騎士だ満足に戦場に立つこともできない"},"kind":"dialogue"},{"uid":"talk.ch15_4_6022#originalText","id":"talk.ch15_4_6022","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"可是，那两人颤抖地拿着剑，拼命想守护他……我不可以见死不救！","en":"But I cannot abandon those girls who shook with fear but still stood up to protect him!","ja":"だけど、震える剣を持って必死に彼を守ろうとするあのふたりを、見捨てることなんてできない!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6023#originalText","id":"talk.ch15_4_6023","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"要是你小看我只是个哥布尔，可就伤脑筋了。","en":"Don't underestimate me because I'm a goblin.","ja":"ゴブリンだと思って舐めてもらっちゃ困る"},"kind":"dialogue"},{"uid":"talk.ch15_4_6024#originalText","id":"talk.ch15_4_6024","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"我柯索吉大爷怎么可能输给一个躲在这种地方的胆小鬼！","en":"I, the great Kosogi, shall not be defeated by a coward, hiding and trembling in a tent!","ja":"こんなところで隠れてた臆病者にこのコソギ様が負けるはずがねえんだよ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6025#originalText","id":"talk.ch15_4_6025","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"喝！","en":"Hah!","ja":"はっ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6026#originalText","id":"talk.ch15_4_6026","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"不管来几次都没用啦！","en":"You can try as many times as you like, but it's futile!","ja":"何度やろうが無駄なんだよ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6027#originalText","id":"talk.ch15_4_6027","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"Release recollection！！","en":"Release Recollection!","ja":"リリース・リコレクション!!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6028#originalText","id":"talk.ch15_4_6028","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"──好漂亮。","en":"It's beautiful.","ja":"――綺麗だ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6029#originalText","id":"talk.ch15_4_6029","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"──简直就像我和……一样。","en":"Just like me and...","ja":"――まるで僕と……のようだ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6030#originalText","id":"talk.ch15_4_6030","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"就跟你说……没用了！","en":"I said...it's futile!","ja":"無駄……なんだよ!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6031#originalText","id":"talk.ch15_4_6031","speaker":{"cn":"柯索吉","en":"Kosogi","ja":"コソギ"},"text":{"cn":"……啊？","en":"...Huh?","ja":"……あ?"},"kind":"dialogue"},{"uid":"talk.ch15_4_6032#originalText","id":"talk.ch15_4_6032","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……呼。","en":"Phew...","ja":"……ふう"},"kind":"dialogue"},{"uid":"talk.ch15_4_6032_2#originalText","id":"talk.ch15_4_6032_2","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"你看起来比较像个骑士了嘛。","en":"Someone's a bit more knightly now.","ja":"少しは騎士っぽくなったじゃない"},"kind":"dialogue"},{"uid":"talk.ch15_4_6033#originalText","id":"talk.ch15_4_6033","speaker":{"cn":"费赛尔","en":"Fizel"},"text":{"cn":"连利仔！","en":"Renlicchi."},"kind":"dialogue"},{"uid":"talk.ch15_4_6034#originalText","id":"talk.ch15_4_6034","speaker":{"cn":"连利","en":"Renly"},"text":{"cn":"啊……","en":"Ack!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6035#originalText","id":"talk.ch15_4_6035","speaker":{"cn":"费赛尔","en":"Fizel"},"text":{"cn":"哦，你看起来比较像个骑士了嘛。这样我们不来帮忙也没问题吧。","en":"Someone's a bit more knightly now. I guess we didn't have to come to your rescue."},"kind":"dialogue"},{"uid":"talk.ch15_4_6036#originalText","id":"talk.ch15_4_6036","speaker":{"cn":"费赛尔","en":"Fizel"},"text":{"cn":"本来还想立战功的说。","en":"We wanted to take credit for that."},"kind":"dialogue"},{"uid":"talk.ch15_4_6037#originalText","id":"talk.ch15_4_6037","speaker":{"cn":"里涅尔","en":"Linel"},"text":{"cn":"哼！可是我们杀的数量比你还多！","en":"Humph! But we did cut off a lot more heads than you!"},"kind":"dialogue"},{"uid":"talk.ch15_4_6038#originalText","id":"talk.ch15_4_6038","speaker":{"cn":"里涅尔 \u0026 费赛尔","en":"Linel \u0026 Fizel","ja":"リネル・フィゼル"},"text":{"cn":"──骑士大人，请您下达命令吧。","en":"Sir Knight, please give us your orders.","ja":"――騎士さま、命令をお願いします"},"kind":"dialogue"},{"uid":"talk.ch15_4_6039#originalText","id":"talk.ch15_4_6039","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……得先确认缇洁她们和桐人先生是否平安无事。","en":"We have to make sure that Tiese, Ronie, and Kirito are safe.","ja":"……ティーゼたちと、キリトさんの無事を確かめないと"},"kind":"dialogue"},{"uid":"talk.ch15_4_6040#originalText","id":"talk.ch15_4_6040","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"这点你不用担心。我们刚才让他们和补给部队会合了。","en":"You don't have to worry about that. We just had those three join the Supply Corps.","ja":"それなら大丈夫キリトたちはさっき、補給部隊に合流させてきた"},"kind":"dialogue"},{"uid":"talk.ch15_4_6041#originalText","id":"talk.ch15_4_6041","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"攻进来的敌军呢？","en":"What about the infiltrating enemies?","ja":"侵入してきた敵兵は?"},"kind":"dialogue"},{"uid":"talk.ch15_4_6042#originalText","id":"talk.ch15_4_6042","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"已经全都解决了。","en":"We wiped them all out.","ja":"全部片付けたです"},"kind":"dialogue"},{"uid":"talk.ch15_4_6043#originalText","id":"talk.ch15_4_6043","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"那……我要回部队了，妳们也回去吧。","en":"Then...I'll be rejoining my unit. You two should do the same.","ja":"じゃあ……僕は部隊に戻るから君たちもそうした方がいいよ"},"kind":"dialogue"},{"uid":"talk.ch15_4_6044#originalText","id":"talk.ch15_4_6044","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"好～","en":"Yes, sir.","ja":"はぁい"},"kind":"dialogue"},{"uid":"talk.ch15_4_6045#originalText","id":"talk.ch15_4_6045","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"明白了。","en":"Understood.","ja":"了解です"},"kind":"dialogue"},{"uid":"talk.ch15_4_6046#originalText","id":"talk.ch15_4_6046","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……谢谢。","en":"Thank you.","ja":"……ありがとう"},"kind":"dialogue"}]};
